<?php use App\Core\View; ?>
<div class="page-head"><div><h1><?= View::e($assignment['exam_title']) ?></h1><p>提交时间：<?= View::e($assignment['submitted_at']??'尚未提交') ?></p></div><a class="btn" href="/student">返回学习中心</a></div>
<section class="card"><div class="grid grid-3"><div class="stat"><strong><?= View::e($assignment['status']) ?></strong><span>答卷状态</span></div><div class="stat"><strong><?= $resultsVisible?View::e($assignment['total_score']??'待评分'):'待发布' ?></strong><span>总分</span></div><div class="stat"><strong><?= $answersVisible?'已开放':'未开放' ?></strong><span>参考答案</span></div></div><?php if($resultsVisible&&$assignment['general_feedback']):?><div class="callout top-gap"><?= View::e($assignment['general_feedback']) ?></div><?php endif;?></section>
<?php foreach($questions as$q):?><article class="card"><div class="question-number">第 <?= $q['display_order'] ?> 题 · 满分 <?= View::e($q['score']) ?></div><h3><?= View::e($q['title']) ?></h3><div class="prompt"><?= View::e($q['prompt']) ?></div><h4>你的答案</h4><div class="answer-reference"><?= View::e($q['answer_text']?:'（未填写）') ?></div><?php if($answersVisible):?><h4>参考答案</h4><div class="answer-reference"><?= View::e($q['reference_answer']) ?></div><?php endif;?><?php if($resultsVisible):?><div class="grid grid-2 top-gap"><div><span class="score-badge"><?= View::e($q['answer_score']??0) ?></span> / <?= View::e($q['score']) ?></div><div><?= View::e($q['feedback']?:'暂无逐题评语') ?></div></div><?php endif;?></article><?php endforeach;?>

